import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# --------------------------------------------------------------------
# CUDA / C++ source
# --------------------------------------------------------------------
cpp_source = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void reduce_sum_dim1_kernel(const __half* __restrict__ input,
                                       __half* __restrict__ output,
                                       int N, int R, int M) {
    // One block per (n, m) output element
    int n = blockIdx.x;      // batch index
    int m = blockIdx.y;      // inner-most dim index
    int tid = threadIdx.x;

    float sum = 0.0f;
    // Stride over the reduction dimension R
    for (int r = tid; r < R; r += BLOCK_SIZE) {
        int idx = n * (R * M) + r * M + m;
        sum += __half2float(input[idx]);
    }

    // Parallel reduction in shared memory
    __shared__ float shmem[BLOCK_SIZE];
    shmem[tid] = sum;
    __syncthreads();

    // Reduce within the block
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shmem[tid] += shmem[tid + stride];
        }
        __syncthreads();
    }

    // Write result (only thread 0)
    if (tid == 0) {
        int out_idx = n * M + m;  // output shape (N, 1, M) flattened
        output[out_idx] = __float2half(shmem[0]);
    }
}

// Wrapper called from Python
torch::Tensor reduce_sum(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::kHalf, "input must be fp16");
    TORCH_CHECK(dim == 1, "this kernel only supports reduction over dim=1");

    auto sizes = input.sizes();
    int64_t N = sizes[0];
    int64_t R = sizes[1];
    int64_t M = sizes[2];

    auto output = torch::empty({N, 1, M}, input.options());

    const int BLOCK_SIZE = 256;
    dim3 block(BLOCK_SIZE);
    dim3 grid(N, M);

    reduce_sum_dim1_kernel<BLOCK_SIZE><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        static_cast<int>(N),
        static_cast<int>(R),
        static_cast<int>(M)
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel error: ") + cudaGetErrorString(err));
    }

    return output;
}
'''

cuda_source = r'''
// Empty string – the kernel is defined in the C++ source above.
// The separate CUDA source is required by load_inline's API but not used.
'''

# Compile the extension
_reduce_ext = load_inline(
    name='reduce_sum_ext',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['reduce_sum'],
    verbose=False,
)


# --------------------------------------------------------------------
# Autograd Function
# --------------------------------------------------------------------
class ReduceSumFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, dim):
        # No backward needed for sum (autograd can handle it automatically)
        return _reduce_ext.reduce_sum(input, dim)

    @staticmethod
    def symbolic(g, input, dim):
        # For ONNX export – use builtin sum
        return g.op("ReduceSum", input, axes_i=[dim], keepdims_i=1)


# --------------------------------------------------------------------
# Model wrapper
# --------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs fp16 sum reduction over a specified dimension using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return ReduceSumFunction.apply(x, self.dim)


# --------------------------------------------------------------------
# Example usage (mirrors reference script)
# --------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    reduce_dim = 1

    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
    model = ModelNew(reduce_dim).cuda()
    y = model(x)

    # Verify correctness against torch.sum
    ref = torch.sum(x, dim=reduce_dim, keepdim=True)
    print('Max diff:', (y - ref).abs().max().item())
